    /// <summary>
    /// check whether PO confirmation is the first one. Assume that document number doesn't exceed 99 for one PO
    /// MPJ_27166_BuyPOFSDEnhancements
    /// </summary>
    /// <param name = "_vendPurchOrderJour">VendPurchOrderJour</param>
    /// <returns>Return True if this is the first confirmation</returns>
    public static boolean metIsFirstConfirmation(PurchId _purchId)
    {
        VendPurchOrderJour localVendPurchOrderJourn;

        select count(RecId) from localVendPurchOrderJourn
            where localVendPurchOrderJourn.PurchId == _purchId;

        return localVendPurchOrderJourn.RecId == 1;
    }

    /// <summary>
    /// Inserts the record and triggers the business event if enabled.
    /// </summary>
    public void insert()
    {      
        next insert();

        var businessEvent = this.getBusinessEvent();
        
        if (businessEvent)
        {
            businessEvent.send();
        }     
    }

    /// <summary>
    /// Gets the business event for the purchase order confirmation if enabled.
    /// </summary>
    /// <returns>BusinessEventsBase</returns>
    protected BusinessEventsBase getBusinessEvent()
    {
        PurchTable  purchTable;
        METPurchaseOrderConfirmedBusinessEvent  businessEvent;

        if (BusinessEventsConfigurationReader::isBusinessEventEnabled(classStr(METPurchaseOrderConfirmedBusinessEvent)))
        {
            purchTable = PurchTable::find(this.PurchId);
            businessEvent = METPurchaseOrderConfirmedBusinessEvent::construct(this, purchTable);
        }

        return businessEvent;
    }
